const zones = [{ name: "Cormano", families: 8420, cov: 92, c: C.orange }, { name: "Bresso", families: 11200, cov: 87, c: "#FF8C42" }, { name: "Cusano M.", families: 6100, cov: 78, c: "#FFB347" }];
